import java.io.Serializable;

/** A row from the Google cluster task-events table. */
public class TaskEvent implements Serializable {
    private static final long serialVersionUID = 1L;

    private long timestamp;
    private String missingInfo;
    private long jobId;
    private long taskIndex;
    private long machineId;
    private int eventType;
    private String userName;
    private int schedulingClass;
    private int priority;
    private double cpuRequest;
    private double ramRequest;
    private double diskRequest;
    private int differentMachineConstraint;

    public TaskEvent() {
    }

    public TaskEvent(long timestamp, String missingInfo, long jobId, long taskIndex,
                     long machineId, int eventType, String userName, int schedulingClass,
                     int priority, double cpuRequest, double ramRequest, double diskRequest,
                     int differentMachineConstraint) {
        this.timestamp = timestamp;
        this.missingInfo = missingInfo;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.machineId = machineId;
        this.eventType = eventType;
        this.userName = userName;
        this.schedulingClass = schedulingClass;
        this.priority = priority;
        this.cpuRequest = cpuRequest;
        this.ramRequest = ramRequest;
        this.diskRequest = diskRequest;
        this.differentMachineConstraint = differentMachineConstraint;
    }

    public TaskEvent(long timestamp, long jobId, long taskIndex, int eventType) {
        this(timestamp, "", jobId, taskIndex, -1L, eventType, "", 0, 0,
                0.0, 0.0, 0.0, 0);
    }

    public static TaskEvent fromCsv(String line) {
        String[] fields = line.split(",", -1);
        if (fields.length != 13) {
            throw new IllegalArgumentException("expected 13 task fields, got " + fields.length);
        }
        return new TaskEvent(
                requiredLong(fields[0], "timestamp"),
                fields[1],
                requiredLong(fields[2], "job ID"),
                requiredLong(fields[3], "task index"),
                optionalLong(fields[4], -1L, "machine ID"),
                requiredInt(fields[5], "event type"),
                fields[6],
                requiredInt(fields[7], "scheduling class"),
                requiredInt(fields[8], "priority"),
                optionalDouble(fields[9], 0.0, "CPU request"),
                optionalDouble(fields[10], 0.0, "RAM request"),
                optionalDouble(fields[11], 0.0, "disk request"),
                optionalInt(fields[12], 0, "different-machine constraint"));
    }

    private static long requiredLong(String value, String field) {
        if (value.isEmpty()) {
            throw new IllegalArgumentException("missing " + field);
        }
        return Long.parseLong(value);
    }

    private static int requiredInt(String value, String field) {
        if (value.isEmpty()) {
            throw new IllegalArgumentException("missing " + field);
        }
        return Integer.parseInt(value);
    }

    private static long optionalLong(String value, long defaultValue, String field) {
        return value.isEmpty() ? defaultValue : Long.parseLong(value);
    }

    private static int optionalInt(String value, int defaultValue, String field) {
        return value.isEmpty() ? defaultValue : Integer.parseInt(value);
    }

    private static double optionalDouble(String value, double defaultValue, String field) {
        return value.isEmpty() ? defaultValue : Double.parseDouble(value);
    }

    public long getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(long timestamp) {
        this.timestamp = timestamp;
    }

    public String getMissingInfo() {
        return missingInfo;
    }

    public void setMissingInfo(String missingInfo) {
        this.missingInfo = missingInfo;
    }

    public long getJobId() {
        return jobId;
    }

    public void setJobId(long jobId) {
        this.jobId = jobId;
    }

    public long getTaskIndex() {
        return taskIndex;
    }

    public void setTaskIndex(long taskIndex) {
        this.taskIndex = taskIndex;
    }

    public long getMachineId() {
        return machineId;
    }

    public void setMachineId(long machineId) {
        this.machineId = machineId;
    }

    public int getEventType() {
        return eventType;
    }

    public void setEventType(int eventType) {
        this.eventType = eventType;
    }

    public String getUserName() {
        return userName;
    }

    public void setUserName(String userName) {
        this.userName = userName;
    }

    public int getSchedulingClass() {
        return schedulingClass;
    }

    public void setSchedulingClass(int schedulingClass) {
        this.schedulingClass = schedulingClass;
    }

    public int getPriority() {
        return priority;
    }

    public void setPriority(int priority) {
        this.priority = priority;
    }

    public double getCpuRequest() {
        return cpuRequest;
    }

    public void setCpuRequest(double cpuRequest) {
        this.cpuRequest = cpuRequest;
    }

    public double getRamRequest() {
        return ramRequest;
    }

    public void setRamRequest(double ramRequest) {
        this.ramRequest = ramRequest;
    }

    public double getDiskRequest() {
        return diskRequest;
    }

    public void setDiskRequest(double diskRequest) {
        this.diskRequest = diskRequest;
    }

    public int getDifferentMachineConstraint() {
        return differentMachineConstraint;
    }

