    private static BufferedReader openReader(String path) throws IOException {
        InputStream input = new FileInputStream(path);
        if (path.endsWith(".gz")) {
            input = new GZIPInputStream(input);
        }
        return new BufferedReader(new InputStreamReader(input, StandardCharsets.UTF_8));
    }

    private static final class LocalFileSink extends RichSinkFunction<String> {
        private final String path;
        private transient BufferedWriter writer;

        private LocalFileSink(String path) {
            this.path = path;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            if (getRuntimeContext().getIndexOfThisSubtask() != 0 || path == null) {
                return;
            }
            File output = new File(path);
            File parent = output.getParentFile();
            if (parent != null) {
                Files.createDirectories(parent.toPath());
            }
            writer = Files.newBufferedWriter(output.toPath(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING);
        }

        @Override
        public void invoke(String value, Context context) throws Exception {
            if (writer != null) {
                writer.write(value);
                writer.newLine();
            }
        }

        @Override
        public void close() throws Exception {
            if (writer != null) {
                writer.close();
            }
        }
    }
