   115	    private static final class LongestStageProcessFunction
   116	            extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, String> {
   117	        private final long sessionMicros;
   118	        private transient ListState<Long> submitTimestamps;
   119	        private transient ValueState<Long> finishTimestamp;
   120	        private transient ValueState<Boolean> emitted;
   121	
   122	        private LongestStageProcessFunction(long sessionMicros) {
   123	            this.sessionMicros = sessionMicros;
   124	        }
   125	
   126	        @Override
   127	        public void open(Configuration parameters) throws Exception {
   128	            submitTimestamps = getRuntimeContext().getListState(
   129	                    new ListStateDescriptor<>("submit timestamps", Long.class));
   130	            finishTimestamp = getRuntimeContext().getState(
   131	                    new ValueStateDescriptor<>("finish timestamp", Long.class));
   132	            emitted = getRuntimeContext().getState(
   133	                    new ValueStateDescriptor<>("result emitted", Boolean.class));
   134	        }
   135	
   136	        @Override
   137	        public void processElement1(TaskEvent event, Context context, Collector<String> out)
   138	                throws Exception {
   139	            if (event.getEventType() != SUBMIT || Boolean.TRUE.equals(emitted.value())) {
   140	                return;
   141	            }
   142	            Long finishedAt = finishTimestamp.value();
   143	            if (finishedAt == null || event.getTimestamp() <= finishedAt) {
   144	                submitTimestamps.add(event.getTimestamp());
   145	            }
   146	        }
   147	
   148	        @Override
   149	        public void processElement2(JobEvent event, Context context, Collector<String> out)
   150	                throws Exception {
   151	            if (event.getEventType() != FINISH || Boolean.TRUE.equals(emitted.value())
   152	                    || event.getTimestamp() == Long.MAX_VALUE) {
   153	                return;
   154	            }
   155	
   156	            Long previousFinish = finishTimestamp.value();
   157	            if (previousFinish == null || event.getTimestamp() < previousFinish) {
   158	                finishTimestamp.update(event.getTimestamp());
   159	                context.timerService().registerEventTimeTimer(timerMillis(event.getTimestamp()));
   160	            }
   161	        }
   162	
   163	        @Override
   164	        public void onTimer(long timestamp, OnTimerContext context, Collector<String> out)
   165	                throws Exception {
   166	            if (Boolean.TRUE.equals(emitted.value())) {
   167	                return;
   168	            }
   169	
   170	            Long finishedAt = finishTimestamp.value();
   171	            if (finishedAt == null) {
   172	                return;
   173	            }
   174	
   175	            List<Long> timestamps = new ArrayList<>();
   176	            for (Long submitTimestamp : submitTimestamps.get()) {
   177	                if (submitTimestamp != null && submitTimestamp <= finishedAt) {
   178	                    timestamps.add(submitTimestamp);
   179	                }
   180	            }
   181	            if (!timestamps.isEmpty()) {
   182	                Collections.sort(timestamps);
   183	                long longestStage = longestStage(timestamps);
   184	                out.collect("(" + context.getCurrentKey() + "," + longestStage + ")");
   185	            }
   186	            emitted.update(true);
   187	        }
   188	
   189	        private long longestStage(List<Long> sortedTimestamps) {
   190	            long longest = 0;
   191	            long current = 0;
   192	            Long previous = null;
   193	            for (long timestamp : sortedTimestamps) {
   194	                if (previous == null || timestamp - previous >= sessionMicros) {
   195	                    current = 1;
   196	                } else {
   197	                    current++;
   198	                }
   199	                longest = Math.max(longest, current);
   200	                previous = timestamp;
   201	            }
   202	            return longest;
   203	        }
   204	    }
