    70	                .addSource(taskSourceOrTest(new TaskEventSource(taskInput)), "task events")
    71	                .setParallelism(1)
    72	                .assignTimestampsAndWatermarks(taskWatermarks());
    73	        DataStream<JobEvent> jobStream = env
    74	                .addSource(jobSourceOrTest(new JobEventSource(jobInput)), "job events")
    75	                .setParallelism(1)
    76	                .assignTimestampsAndWatermarks(jobWatermarks());
