   100	    private static long toMillis(long timestampMicros) {
   101	        if (timestampMicros == Long.MAX_VALUE) {
   102	            return Long.MAX_VALUE;
   103	        }
   104	        return Math.floorDiv(timestampMicros, MICROS_PER_MILLISECOND);
