    private static final class TaskEventSource extends RichParallelSourceFunction<TaskEvent> {
        private final String path;
        private volatile boolean running = true;

        private TaskEventSource(String path) {
            this.path = path;
        }

        @Override
        public void run(SourceContext<TaskEvent> context) throws Exception {
            if (path == null) {
                return;
            }
            try (BufferedReader reader = openReader(path)) {
                String line;
                long lineNumber = 0;
                while (running && (line = reader.readLine()) != null) {
                    lineNumber++;
                    if (line.isEmpty()) {
                        continue;
                    }
                    try {
