   189	        private long longestStage(List<Long> sortedTimestamps) {
   190	            long longest = 0;
   191	            long current = 0;
   192	            Long previous = null;
   193	            for (long timestamp : sortedTimestamps) {
   194	                if (previous == null || timestamp - previous >= sessionMicros) {
   195	                    current = 1;
   196	                } else {
   197	                    current++;
   198	                }
   199	                longest = Math.max(longest, current);
   200	                previous = timestamp;
   201	            }
   202	            return longest;
   203	        }
