    42	    private static final long MICROS_PER_SECOND = 1_000_000L;
    43	    private static final long MICROS_PER_MILLISECOND = 1_000L;
    44	    private static final Duration MAX_OUT_OF_ORDERNESS = Duration.ofHours(24);
    45	
    46	    public static void main(String[] args) throws Exception {
    47	        ParameterTool params = ParameterTool.fromArgs(args);
    48	        String taskInput = params.get("task_input", null);
    49	        String jobInput = params.get("job_input", null);
    50	        String outputPath = params.get("output", null);
    51	        int sessionSeconds = params.getInt("sesssize", 600);
    52	
    53	        if (sessionSeconds <= 0) {
    54	            throw new IllegalArgumentException("sesssize must be positive");
    55	        }
    56	        if (taskInput == null && taskEvents == null) {
    57	            throw new IllegalArgumentException("missing required parameter: task_input");
    58	        }
    59	        if (jobInput == null && jobEvents == null) {
    60	            throw new IllegalArgumentException("missing required parameter: job_input");
    61	        }
    62	        if (outputPath == null && out == null) {
    63	            throw new IllegalArgumentException("missing required parameter: output");
    64	        }
    65	
    66	        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    67	        env.setParallelism(1);
    68	
    69	        DataStream<TaskEvent> taskStream = env
    70	                .addSource(taskSourceOrTest(new TaskEventSource(taskInput)), "task events")
    71	                .setParallelism(1)
    72	                .assignTimestampsAndWatermarks(taskWatermarks());
    73	        DataStream<JobEvent> jobStream = env
    74	                .addSource(jobSourceOrTest(new JobEventSource(jobInput)), "job events")
    75	                .setParallelism(1)
    76	                .assignTimestampsAndWatermarks(jobWatermarks());
    77	
    78	        long sessionMicros = Math.multiplyExact((long) sessionSeconds, MICROS_PER_SECOND);
    79	        DataStream<String> results = taskStream
    80	                .keyBy(TaskEvent::getJobId)
    81	                .connect(jobStream.keyBy(JobEvent::getJobId))
    82	                .process(new LongestStageProcessFunction(sessionMicros));
    83	
    84	        @SuppressWarnings("unchecked")
    85	        SinkFunction<String> sink = (SinkFunction<String>) sinkOrTest(new LocalFileSink(outputPath));
    86	        results.addSink(sink).setParallelism(1);
    87	        env.execute("LongestSessionPerJob");
