    90	    private static WatermarkStrategy<TaskEvent> taskWatermarks() {
    91	        return WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(MAX_OUT_OF_ORDERNESS)
    92	                .withTimestampAssigner((event, recordTimestamp) -> toMillis(event.getTimestamp()));
    93	    }
    94	
    95	    private static WatermarkStrategy<JobEvent> jobWatermarks() {
    96	        return WatermarkStrategy.<JobEvent>forBoundedOutOfOrderness(MAX_OUT_OF_ORDERNESS)
    97	                .withTimestampAssigner((event, recordTimestamp) -> toMillis(event.getTimestamp()));
    98	    }
