   100	    private static long toMillis(long timestampMicros) {
   101	        if (timestampMicros == Long.MAX_VALUE) {
   102	            return Long.MAX_VALUE;
   103	        }
   104	        return Math.floorDiv(timestampMicros, MICROS_PER_MILLISECOND);
   105	    }
   106	
   107	    private static long timerMillis(long timestampMicros) {
   108	        if (timestampMicros >= Long.MAX_VALUE - (MICROS_PER_MILLISECOND - 1)) {
   109	            return Long.MAX_VALUE;
   110	        }
   111	        return Math.floorDiv(timestampMicros + MICROS_PER_MILLISECOND - 1,
   112	                MICROS_PER_MILLISECOND);
   113	    }
