   212	        }
   213	
   214	        @Override
   215	        public void run(SourceContext<TaskEvent> context) throws Exception {
   216	            if (path == null) {
   217	                return;
   218	            }
   219	            try (BufferedReader reader = openReader(path)) {
   220	                String line;
   221	                long lineNumber = 0;
   222	                while (running && (line = reader.readLine()) != null) {
   223	                    lineNumber++;
   224	                    if (line.isEmpty()) {
   225	                        continue;
   226	                    }
   227	                    try {
   228	                        context.collect(TaskEvent.fromCsv(line));
