                0.0, 0.0, 0.0, 0);
    }

    public static TaskEvent fromCsv(String line) {
        String[] fields = line.split(",", -1);
        if (fields.length != 13) {
            throw new IllegalArgumentException("expected 13 task fields, got " + fields.length);
        }
        return new TaskEvent(
                requiredLong(fields[0], "timestamp"),
                fields[1],
                requiredLong(fields[2], "job ID"),
                requiredLong(fields[3], "task index"),
                optionalLong(fields[4], -1L, "machine ID"),
                requiredInt(fields[5], "event type"),
                fields[6],
