    }

    private static int optionalInt(String value, int defaultValue, String field) {
        return value.isEmpty() ? defaultValue : Integer.parseInt(value);
    }

    private static double optionalDouble(String value, double defaultValue, String field) {
        return value.isEmpty() ? defaultValue : Double.parseDouble(value);
    }

