import clusterdata.datatypes.JobEvent;
import clusterdata.datatypes.TaskEvent;
import clusterdata.utils.AppBase;
import org.apache.flink.api.common.eventtime.WatermarkStrategy;
import org.apache.flink.api.common.state.ListState;
import org.apache.flink.api.common.state.ListStateDescriptor;
import org.apache.flink.api.common.state.ValueState;
import org.apache.flink.api.common.state.ValueStateDescriptor;
import org.apache.flink.api.java.utils.ParameterTool;
import org.apache.flink.configuration.Configuration;
import org.apache.flink.streaming.api.datastream.DataStream;
import org.apache.flink.streaming.api.environment.StreamExecutionEnvironment;
import org.apache.flink.streaming.api.functions.co.KeyedCoProcessFunction;
import org.apache.flink.streaming.api.functions.sink.RichSinkFunction;
import org.apache.flink.streaming.api.functions.sink.SinkFunction;
import org.apache.flink.streaming.api.functions.source.RichParallelSourceFunction;
import org.apache.flink.streaming.api.watermark.Watermark;
import org.apache.flink.util.Collector;

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.StandardOpenOption;
import java.time.Duration;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.zip.GZIPInputStream;

public class LongestSessionPerJob extends AppBase {
    private static final int SUBMIT = 0;
    private static final int FINISH = 4;
    private static final long MICROS_PER_SECOND = 1_000_000L;
    private static final long MICROS_PER_MILLISECOND = 1_000L;
    private static final Duration MAX_OUT_OF_ORDERNESS = Duration.ofHours(24);

    public static void main(String[] args) throws Exception {
        ParameterTool params = ParameterTool.fromArgs(args);
        String taskInput = params.get("task_input", null);
        String jobInput = params.get("job_input", null);
        String outputPath = params.get("output", null);
        int sessionSeconds = params.getInt("sesssize", 600);

        if (sessionSeconds <= 0) {
            throw new IllegalArgumentException("sesssize must be positive");
        }
        if (taskInput == null && taskEvents == null) {
            throw new IllegalArgumentException("missing required parameter: task_input");
        }
        if (jobInput == null && jobEvents == null) {
            throw new IllegalArgumentException("missing required parameter: job_input");
        }
        if (outputPath == null && out == null) {
            throw new IllegalArgumentException("missing required parameter: output");
        }

        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(1);

        DataStream<TaskEvent> taskStream = env
                .addSource(taskSourceOrTest(new TaskEventSource(taskInput)), "task events")
                .setParallelism(1)
                .assignTimestampsAndWatermarks(taskWatermarks());
        DataStream<JobEvent> jobStream = env
                .addSource(jobSourceOrTest(new JobEventSource(jobInput)), "job events")
                .setParallelism(1)
                .assignTimestampsAndWatermarks(jobWatermarks());

        long sessionMicros = Math.multiplyExact((long) sessionSeconds, MICROS_PER_SECOND);
        DataStream<String> results = taskStream
                .keyBy(TaskEvent::getJobId)
                .connect(jobStream.keyBy(JobEvent::getJobId))
                .process(new LongestStageProcessFunction(sessionMicros));

        @SuppressWarnings("unchecked")
        SinkFunction<String> sink = (SinkFunction<String>) sinkOrTest(new LocalFileSink(outputPath));
        results.addSink(sink).setParallelism(1);
        env.execute("LongestSessionPerJob");
    }

    private static WatermarkStrategy<TaskEvent> taskWatermarks() {
        return WatermarkStrategy.<TaskEvent>forBoundedOutOfOrderness(MAX_OUT_OF_ORDERNESS)
                .withTimestampAssigner((event, recordTimestamp) -> toMillis(event.getTimestamp()));
    }

    private static WatermarkStrategy<JobEvent> jobWatermarks() {
        return WatermarkStrategy.<JobEvent>forBoundedOutOfOrderness(MAX_OUT_OF_ORDERNESS)
                .withTimestampAssigner((event, recordTimestamp) -> toMillis(event.getTimestamp()));
    }

    private static long toMillis(long timestampMicros) {
        if (timestampMicros == Long.MAX_VALUE) {
            return Long.MAX_VALUE;
        }
        return Math.floorDiv(timestampMicros, MICROS_PER_MILLISECOND);
    }

    private static long timerMillis(long timestampMicros) {
        if (timestampMicros >= Long.MAX_VALUE - (MICROS_PER_MILLISECOND - 1)) {
            return Long.MAX_VALUE;
        }
        return Math.floorDiv(timestampMicros + MICROS_PER_MILLISECOND - 1,
                MICROS_PER_MILLISECOND);
    }

    private static final class LongestStageProcessFunction
            extends KeyedCoProcessFunction<Long, TaskEvent, JobEvent, String> {
        private final long sessionMicros;
        private transient ListState<Long> submitTimestamps;
        private transient ValueState<Long> finishTimestamp;
        private transient ValueState<Boolean> emitted;

        private LongestStageProcessFunction(long sessionMicros) {
            this.sessionMicros = sessionMicros;
        }

        @Override
        public void open(Configuration parameters) throws Exception {
            submitTimestamps = getRuntimeContext().getListState(
                    new ListStateDescriptor<>("submit timestamps", Long.class));
            finishTimestamp = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("finish timestamp", Long.class));
            emitted = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("result emitted", Boolean.class));
        }

        @Override
        public void processElement1(TaskEvent event, Context context, Collector<String> out)
                throws Exception {
            if (event.getEventType() != SUBMIT || Boolean.TRUE.equals(emitted.value())) {
                return;
            }
            Long finishedAt = finishTimestamp.value();
            if (finishedAt == null || event.getTimestamp() <= finishedAt) {
                submitTimestamps.add(event.getTimestamp());
            }
        }

        @Override
        public void processElement2(JobEvent event, Context context, Collector<String> out)
                throws Exception {
            if (event.getEventType() != FINISH || Boolean.TRUE.equals(emitted.value())
                    || event.getTimestamp() == Long.MAX_VALUE) {
                return;
            }

